import { loadFont as loadRubik } from "@remotion/google-fonts/Rubik";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// VETS SALES (Gabriel Amorim). Motion horizontal de 62 s sobre a locução (ElevenLabs, voz "o locutor", cortada em 59,4 s:
// depois disso o mp3 trazia um texto de outro cliente). Tom consultivo e sério, para dono de hospital veterinário.
// Identidade do PDF: azul-claro do logo, azul-marinho dos títulos, fundo claro e liso. O balde furado é a metáfora do PDF.
// Problema com visual genérico (conversas de WhatsApp quaisquer); telas do sistema só depois de "existe a Vets Sales".
// Telas redesenhadas com dados fictícios: os prints do cliente têm telefones e nomes reais.
// O texto entra e fica parado; o movimento contínuo fica na câmera de cada cena e nos objetos.
// V2: voz nova (voz-v2.mp3, 67,7 s) com a frase "acompanha os resultados e as conversas pelo computador e pelo celular, em
// tempo real". As cenas da v1 seguem nos tempos da voz antiga: `toOld` converte o tempo novo no antigo, palavra por palavra.
// A cena nova (TempoReal) usa o tempo novo direto: dashboard real do PDF no computador e prints do app no celular
// (conversas com nomes e números desfocados).

const { fontFamily: H } = loadRubik("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: U } = loadInter("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const VS2_FPS = 30;
const VS_FPS = VS2_FPS;
export const VS2_DUR = 70.0;
export const VS2_FRAMES = Math.round(VS2_DUR * VS2_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });

const PAPER = "#F4F6FA";
const WHITE = "#FFFFFF";
const NAVY = "#1E1B5E";
const NAVY_D = "#16134A";
const MUTED = "#6E7191";
const LINE = "#E2E6F0";
const BLUE = "#81B0E6";
const BLUE_D = "#3F74D4";
const BLUE_L = "#E6EFFB";
const RED = "#E0564B";
const RED_L = "#FCE9E7";
const GREEN = "#1FAF5A";
const GREEN_L = "#E3F6EA";
const WA = "#25D366";
const WA_D = "#0B7A5E";
const GOLD = "#F2B84B";
const SHADOW = "0 30px 70px rgba(30,27,94,0.12), 0 4px 14px rgba(30,27,94,0.07)";


// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 14).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};
const popIn = (t: number, at: number, from = 0.6, dy = 30): React.CSSProperties => {
  const e = pop(t, at, 0.5);
  return { opacity: Math.min(1, k(t, at, 0.25) * 1.4), transform: `translateY(${((1 - e) * dy).toFixed(1)}px) scale(${(from + (1 - from) * e).toFixed(4)})` };
};

type L = [string, number, string?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; left?: number; right?: number; align?: "center" | "flex-start"; color?: string; out?: number; weight?: number; gap?: number }> = ({ t, items, size, top, left = 120, right = 120, align = "center", color = NAVY, out, weight = 700, gap = 1.1 }) => (
  <div style={{ position: "absolute", left, right, top, display: "flex", flexDirection: "column", alignItems: align }}>
    {items.map(([w, at, c], i) => (
      <div key={i} style={{ fontFamily: H, fontWeight: weight, fontSize: size, lineHeight: gap, letterSpacing: "-0.025em", whiteSpace: "nowrap", color: c ?? color, transformOrigin: align === "center" ? "center" : "left center", ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// câmera da cena: deriva lenta e contínua, cada cena numa direção; `hits` = batida curta na palavra forte
const Cam: React.FC<{ t: number; a: number; b: number; from: [number, number, number]; to: [number, number, number]; hits?: number[]; children: React.ReactNode }> = ({ t, a, b, from, to, hits = [], children }) => {
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.bezier(0.33, 0, 0.25, 1) });
  const h = hits.reduce((acc, at) => acc + (t >= at ? 0.04 * Math.exp(-(t - at) * 5) * Math.min(1, (t - at) / 0.06) : 0), 0);
  const s = from[0] + (to[0] - from[0]) * p + h, x = from[1] + (to[1] - from[1]) * p, y = from[2] + (to[2] - from[2]) * p;
  return <AbsoluteFill style={{ transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${s.toFixed(4)})` }}>{children}</AbsoluteFill>;
};

const draw = (t: number, a: number, d = 0.6) => {
  const e = interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
  return { strokeDasharray: 1, strokeDashoffset: 1 - e, opacity: e > 0 ? 1 : 0 } as React.CSSProperties;
};
const SW = { fill: "none", strokeLinecap: "round", strokeLinejoin: "round" } as const;

// ───────── ícones ─────────
const WA_BUBBLE = "M50 20a30 30 0 0 0-25.6 45.6L20 80l14.8-4.2A30 30 0 1 0 50 20z";
const WA_PHONE = "M39 36c1-2 2.6-2 3.6-1.6l3 6.4c.4 1-.2 2-1 2.8l-1.4 1.4c1.6 3.6 4.6 6.6 8.2 8.2l1.4-1.4c.8-.8 1.8-1.4 2.8-1l6.4 3c.4 1 .4 2.6-1.6 3.6-2.6 1.4-6 1.6-10.6-1-4.6-2.6-8.8-6.8-11.4-11.4-2.6-4.6-2.4-8-1-10.6z";
const WaIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg viewBox="0 0 100 100" width={size} height={size}>
    <circle cx={50} cy={50} r={50} fill={WA} />
    <path d={WA_BUBBLE} fill="none" stroke={WHITE} strokeWidth={5.5} strokeLinejoin="round" />
    <path d={WA_PHONE} fill={WHITE} />
  </svg>
);
const IgIcon: React.FC<{ size: number; id: string }> = ({ size, id }) => (
  <svg viewBox="0 0 100 100" width={size} height={size}>
    <defs>
      <linearGradient id={id} x1="0" y1="1" x2="1" y2="0">
        <stop offset="0" stopColor="#FEDA75" />
        <stop offset="0.3" stopColor="#FA7E1E" />
        <stop offset="0.6" stopColor="#D62976" />
        <stop offset="1" stopColor="#4F5BD5" />
      </linearGradient>
    </defs>
    <rect x={0} y={0} width={100} height={100} rx={28} fill={`url(#${id})`} />
    <rect x={22} y={22} width={56} height={56} rx={17} fill="none" stroke={WHITE} strokeWidth={6.5} />
    <circle cx={50} cy={50} r={13} fill="none" stroke={WHITE} strokeWidth={6.5} />
    <circle cx={67.5} cy={32.5} r={4} fill={WHITE} />
  </svg>
);
const Badge: React.FC<{ ch: "wa" | "ig"; size: number; id: string }> = ({ ch, size, id }) => (ch === "wa" ? <WaIcon size={size} /> : <IgIcon size={size} id={id} />);
const Check: React.FC<{ size: number; bg?: string }> = ({ size, bg = GREEN }) => (
  <svg viewBox="0 0 40 40" width={size} height={size} style={{ flexShrink: 0 }}>
    <circle cx={20} cy={20} r={20} fill={bg} />
    <path d="M12 20.5l5.5 5.5L28.5 14" stroke={WHITE} strokeWidth={4} {...SW} />
  </svg>
);
const Clock: React.FC = () => (
  <svg viewBox="0 0 30 30" width={28} height={28}><circle cx={15} cy={15} r={12} stroke={RED} strokeWidth={3.2} fill="none" /><path d="M15 8v7.5l5 3" stroke={RED} strokeWidth={3.2} {...SW} /></svg>
);
const Megafone: React.FC<{ size: number }> = ({ size }) => (
  <svg viewBox="0 0 40 40" width={size} height={size}><path d="M7 16v8h6l12 7V9l-12 7H7z" fill={BLUE_D} /><path d="M30 14q5 6 0 12" stroke={BLUE_D} strokeWidth={3} {...SW} /></svg>
);
const Avatar: React.FC<{ name: string; size: number; color: string }> = ({ name, size, color }) => (
  <div style={{ width: size, height: size, borderRadius: size, background: color, color: WHITE, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: U, fontWeight: 600, fontSize: size * 0.42, flexShrink: 0 }}>{name[0]}</div>
);
const Logo: React.FC<{ width: number }> = ({ width }) => (
  <div style={{ background: BLUE, borderRadius: width * 0.045, padding: `${width * 0.07}px ${width * 0.08}px`, display: "inline-flex" }}>
    <Img src={staticFile("vetssales/logo-branco.png")} style={{ width: width * 0.84, display: "block" }} />
  </div>
);

// ───────── o balde ─────────
const HOLES: [number, number, number][] = [[165, 330, -1], [262, 392, 1], [348, 300, 1], [205, 230, -1]];
const BODY = "M50 90 L100 470 Q250 505 400 470 L450 90 Z";
const Bucket: React.FC<{ t: number; holesAt?: number; patchAt?: number[]; fill: number; coinsFrom?: number; dark?: boolean; size: number; id: string }> = ({ t, holesAt, patchAt = [], fill, coinsFrom, dark = false, size, id }) => {
  const ink = dark ? WHITE : NAVY;
  const body = dark ? "rgba(255,255,255,0.10)" : "#E9EEF7";
  const lvl = 470 - fill * 330;
  const holes = HOLES.map(([hx, hy, dir], i) => {
    const open = holesAt === undefined ? 0 : pop(t, holesAt + i * 0.12, 0.35);
    const patched = patchAt[i] === undefined ? 0 : pop(t, patchAt[i], 0.4);
    const below = hy > lvl - 4 ? 1 : 0;
    return { hx, hy, dir, open, patched, leak: open * (1 - patched) * below, i };
  });
  const leaking = holes.reduce((a, h) => a + h.leak, 0) / holes.length;
  return (
    <svg viewBox="0 0 500 560" width={size} height={size * 1.12} style={{ overflow: "visible" }}>
      <defs>
        <clipPath id={id}><path d={BODY} /></clipPath>
      </defs>
      <ellipse cx={250} cy={520} rx={60 + leaking * 190} ry={10 + leaking * 16} fill={BLUE} opacity={0.35 * Math.min(1, leaking * 2)} />
      {coinsFrom !== undefined
        ? [0, 1, 2, 3].map((j) => {
            const ph = (t - coinsFrom - j * 0.32) * 0.9;
            if (ph < 0) return null;
            const p = ph % 1;
            const y = -260 + p * (lvl - 30 + 260);
            const x = 250 + [-60, 40, -10, 70][j];
            return (
              <g key={j} transform={`translate(${x} ${y}) rotate(${(p * 220 + j * 40).toFixed(0)})`} opacity={p > 0.92 ? (1 - p) / 0.08 : 1}>
                <circle r={20} fill={GOLD} stroke="#C98B1E" strokeWidth={4} />
                <text y={7} textAnchor="middle" fontFamily={U} fontWeight={700} fontSize={20} fill="#9A6510">$</text>
              </g>
            );
          })
        : null}
      <path d={BODY} fill={body} />
      <g clipPath={`url(#${id})`}>
        <rect x={0} y={lvl} width={500} height={600} fill={BLUE} opacity={0.85} />
        <ellipse cx={250} cy={lvl} rx={240} ry={22} fill="#A9C9F0" />
      </g>
      <path d="M50 90 L100 470 Q250 505 400 470 L450 90" stroke={ink} strokeWidth={9} {...SW} />
      <ellipse cx={250} cy={90} rx={200} ry={30} stroke={ink} strokeWidth={9} fill="none" />
      <path d="M62 120 Q250 -120 438 120" stroke={ink} strokeWidth={7} fill="none" opacity={0.85} />
      {holes.map((h) => (
        <g key={h.i}>
          <ellipse cx={h.hx} cy={h.hy} rx={15 * h.open} ry={11 * h.open} fill={NAVY_D} />
          {h.patched > 0 ? (
            <g transform={`translate(${h.hx} ${h.hy}) scale(${h.patched}) rotate(${h.dir * 8})`}>
              <rect x={-30} y={-22} width={60} height={44} rx={10} fill={BLUE_D} />
              <path d="M-18 -10 L-18 10 M0 -10 L0 10 M18 -10 L18 10" stroke={WHITE} strokeWidth={4} strokeLinecap="round" opacity={0.9} />
            </g>
          ) : null}
          {h.leak > 0.02
            ? [0, 1, 2, 3, 4, 5].map((j) => {
                const p = (t * 1.5 + j / 6 + h.i * 0.17) % 1;
                const x = h.hx + h.dir * (14 + p * 120);
                const y = h.hy + 6 + p * p * 240;
                return (j + h.i) % 3 === 0 ? (
                  <g key={j} transform={`translate(${x} ${y}) rotate(${(p * 300).toFixed(0)})`} opacity={h.leak * (1 - p * 0.6)}>
                    <circle r={13} fill={GOLD} stroke="#C98B1E" strokeWidth={3} />
                  </g>
                ) : (
                  <ellipse key={j} cx={x} cy={y} rx={7} ry={10} fill={BLUE_D} opacity={h.leak * (1 - p * 0.5)} />
                );
              })
            : null}
        </g>
      ))}
    </svg>
  );
};

// ───────── 1 · abertura ─────────
const Hospital: React.FC<{ t: number }> = ({ t }) => (
  <svg viewBox="0 0 300 260" width={300} height={260}>
    <path d="M30 240 V110 L150 40 L270 110 V240 Z" stroke={NAVY} strokeWidth={10} {...SW} style={draw(t, 0.05, 0.6)} pathLength={1} />
    <path d="M10 240 H290" stroke={NAVY} strokeWidth={10} {...SW} style={draw(t, 0.2, 0.4)} pathLength={1} />
    <g style={{ transformOrigin: "150px 150px", transform: `scale(${pop(t, 0.35, 0.5)})` }}>
      <circle cx={150} cy={150} r={52} fill={BLUE} />
      <ellipse cx={150} cy={162} rx={17} ry={14} fill={WHITE} />
      <circle cx={128} cy={138} r={7.5} fill={WHITE} />
      <circle cx={142} cy={126} r={7.5} fill={WHITE} />
      <circle cx={158} cy={126} r={7.5} fill={WHITE} />
      <circle cx={172} cy={138} r={7.5} fill={WHITE} />
    </g>
  </svg>
);
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const outA = lin(t, 1.25, 1.45);
  const bars = [170, 230, 280, 330];
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <div style={{ position: "absolute", left: 960 - 150, top: 210, opacity: 1 - outA, transform: `scale(${(1 - outA * 0.1).toFixed(3)})` }}><Hospital t={t} /></div>
      <Lines t={t} items={[["Seu hospital veterinário", 0.25]]} size={104} top={560} out={1.25} />
      <Lines t={t} items={[["pode estar deixando de", 1.45], ["faturar mais", 2.4, BLUE_D]]} size={92} top={170} gap={1.2} />
      <div style={{ position: "absolute", left: 960 - 330, top: 520, width: 660, height: 400, display: "flex", alignItems: "flex-end", gap: 44 }}>
        {bars.map((h, i) => {
          const e = k(t, 1.55 + i * 0.12, 0.6);
          return <div key={i} style={{ width: 120, height: h * e, background: i === 3 ? BLUE_D : BLUE, borderRadius: "16px 16px 6px 6px", opacity: e > 0 ? 1 : 0 }} />;
        })}
        <div style={{ width: 120, height: 400 * k(t, 2.45, 0.7), border: `6px dashed ${RED}`, borderRadius: "16px 16px 6px 6px", boxSizing: "border-box", opacity: k(t, 2.45, 0.2), display: "flex", alignItems: "flex-start", justifyContent: "center", paddingTop: 26 }}>
          <span style={{ fontFamily: H, fontWeight: 700, fontSize: 60, color: RED, opacity: k(t, 2.8, 0.3) }}>?</span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── 2 · balde furado ─────────
const Balde: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: PAPER }}>
    <Lines t={t} items={[["Seu processo", 4.15], ["comercial é um", 4.6], ["balde furado", 5.6, RED]]} size={104} top={250} left={240} right={820} align="flex-start" gap={1.15} />
    <div style={{ position: "absolute", left: 1110, top: 230 }}>
      <Bucket id="bk1" t={t} holesAt={5.9} fill={0.72 - 0.25 * lin(t, 6.0, 7.0)} coinsFrom={3.55} size={540} />
    </div>
  </AbsoluteFill>
);

// ───────── 3 · divulgação e mensagens ─────────
const NOTES: [string, string][] = [["Juliana", "Oi, quanto é a consulta?"], ["Rafael", "Vocês atendem sábado?"], ["Carla", "Preciso vacinar meu gato"], ["Pedro", "Tem horário hoje?"]];
const Divulgacao: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: PAPER }}>
    <Lines t={t} items={[["Você investe em divulgação", 6.85]]} size={78} top={90} out={8.3} />
    <Lines t={t} items={[["e recebe mensagens no WhatsApp", 8.4]]} size={78} top={90} />
    <div style={{ position: "absolute", left: 250, top: 300, width: 440, height: 560, background: WHITE, borderRadius: 34, boxShadow: SHADOW, padding: 30, boxSizing: "border-box", ...popIn(t, 7.4, 0.7, 50) }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
        <div style={{ width: 54, height: 54, borderRadius: 54, background: BLUE_L, display: "flex", alignItems: "center", justifyContent: "center" }}><Megafone size={30} /></div>
        <div>
          <div style={{ fontFamily: U, fontWeight: 700, fontSize: 24, color: NAVY }}>Seu Hospital Vet</div>
          <div style={{ fontFamily: U, fontWeight: 500, fontSize: 19, color: MUTED }}>Patrocinado</div>
        </div>
      </div>
      <div style={{ marginTop: 24, height: 270, borderRadius: 22, background: BLUE_L, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <svg viewBox="0 0 120 120" width={170} height={170}>
          <ellipse cx={60} cy={76} rx={26} ry={21} fill={BLUE} />
          <circle cx={26} cy={48} r={11} fill={BLUE} /><circle cx={46} cy={30} r={11} fill={BLUE} /><circle cx={74} cy={30} r={11} fill={BLUE} /><circle cx={94} cy={48} r={11} fill={BLUE} />
        </svg>
      </div>
      <div style={{ marginTop: 26, height: 64, borderRadius: 16, background: NAVY, color: WHITE, fontFamily: U, fontWeight: 600, fontSize: 24, display: "flex", alignItems: "center", justifyContent: "center", gap: 12 }}>
        <WaIcon size={32} /> Enviar mensagem
      </div>
    </div>
    <svg viewBox="0 0 300 80" width={300} height={80} style={{ position: "absolute", left: 750, top: 540 }}>
      <path d="M10 40 H250" stroke={BLUE_D} strokeWidth={8} strokeDasharray="4 20" strokeLinecap="round" fill="none" style={{ clipPath: `inset(0 ${(100 - 100 * k(t, 8.3, 0.6)).toFixed(1)}% 0 0)` }} />
      <path d="M250 18 L280 40 L250 62" stroke={BLUE_D} strokeWidth={8} {...SW} opacity={k(t, 8.75, 0.2)} />
    </svg>
    <div style={{ position: "absolute", left: 1110, top: 250, width: 560, height: 700, ...popIn(t, 8.45, 0.8, 60) }}>
      <div style={{ position: "absolute", inset: 0, background: NAVY_D, borderRadius: 64, padding: 16 }}>
        <div style={{ width: "100%", height: "100%", borderRadius: 50, background: "linear-gradient(160deg,#2A2878,#1E1B5E)", position: "relative", overflow: "hidden" }}>
          <div style={{ position: "absolute", top: 56, width: "100%", textAlign: "center", fontFamily: U, fontWeight: 600, fontSize: 84, color: WHITE, letterSpacing: "-0.02em" }}>21:14</div>
          {NOTES.map(([n, m], i) => {
            const at = 8.8 + i * 0.22;
            const e = pop(t, at, 0.4);
            return (
              <div key={i} style={{ position: "absolute", left: 24, right: 24, top: 210 + i * 108, height: 94, background: "rgba(255,255,255,0.94)", borderRadius: 24, display: "flex", alignItems: "center", gap: 16, padding: "0 20px", boxSizing: "border-box", opacity: Math.min(1, k(t, at, 0.2) * 1.5), transform: `translateY(${((1 - e) * -40).toFixed(1)}px) scale(${(0.85 + 0.15 * e).toFixed(3)})` }}>
                <WaIcon size={46} />
                <div style={{ minWidth: 0 }}>
                  <div style={{ fontFamily: U, fontWeight: 700, fontSize: 22, color: NAVY }}>{n}</div>
                  <div style={{ fontFamily: U, fontWeight: 500, fontSize: 21, color: MUTED, whiteSpace: "nowrap" }}>{m}</div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
      <div style={{ position: "absolute", right: -22, top: -22, width: 76, height: 76, borderRadius: 76, background: RED, color: WHITE, fontFamily: U, fontWeight: 700, fontSize: 34, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, 9.1, 0.4)})` }}>
        {Math.max(1, Math.min(12, Math.round(interpolate(t, [9.1, 9.9], [1, 12], cl))))}
      </div>
    </div>
  </AbsoluteFill>
);

// ───────── 4 · as oportunidades escapam ─────────
const Escapam: React.FC<{ t: number }> = ({ t }) => {
  const Y = 610;
  const gaps = [[700, 820], [1160, 1280]];
  const track = k(t, 10.25, 0.7);
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      <Lines t={t} items={[["Mas, até o agendamento,", 10.45]]} size={80} top={130} out={12.15} />
      <Lines t={t} items={[["as oportunidades escapam", 12.25, RED]]} size={88} top={125} />
      <svg viewBox="0 0 1920 1080" width={1920} height={1080} style={{ position: "absolute", inset: 0 }}>
        {[[330, 700], [820, 1160], [1280, 1590]].map(([a, b], i) => (
          <path key={i} d={`M${a} ${Y} H${b}`} stroke={NAVY} strokeWidth={14} strokeLinecap="round" fill="none" pathLength={1} style={draw(t, 10.25 + i * 0.15, 0.5)} />
        ))}
        {gaps.map(([a, b], i) => (
