const pw = (x: number, from: number, to: number) => {
  for (let i = 1; i < ANCH.length; i++) {
    const a = ANCH[i - 1], b = ANCH[i];
    if (x <= b[from]) return a[to] + ((b[to] - a[to]) * (x - a[from])) / Math.max(1e-6, b[from] - a[from]);
  }
  return ANCH[ANCH.length - 1][to] + (x - ANCH[ANCH.length - 1][from]);
};
