type Enter = "none" | "zoom" | "slideL" | "slideU" | "wipe" | "circle" | "zoomOut";
type V3 = [number, number, number];
type Sc = { C: React.FC<{ t: number }>; enter: Enter; cam: [V3, V3]; hits?: number[]; a: number; b: number; nova?: boolean };
const T_OLD = [0, 3.6, 6.55, 10.15, 13.65, 21.8, 25.0, 31.6, 35.45, 38.0, 42.45, 46.95, 49.8, 55.5, 62];
const OLD: Omit<Sc, "a" | "b">[] = [
  { C: Abertura, enter: "none", cam: [[1.14, 0, 30], [1.0, 0, 0]], hits: [2.43] },
  { C: Balde, enter: "zoom", cam: [[1.0, 40, 0], [1.08, -30, -10]], hits: [5.67] },
  { C: Divulgacao, enter: "slideL", cam: [[1.08, 90, 20], [1.0, -40, 0]], hits: [8.79] },
  { C: Escapam, enter: "slideU", cam: [[1.1, 120, 0], [1.02, -30, 0]], hits: [12.31] },
  { C: Tutores, enter: "zoom", cam: [[1, 0, 20], [1, 0, -20]], hits: [14.75, 17.5, 20.3] },
  { C: Brechas, enter: "wipe", cam: [[1.0, 0, 20], [1.07, 0, -20]], hits: [23.07] },
  { C: IA, enter: "circle", cam: [[1.08, 60, 30], [1.0, -20, 0]], hits: [27.91] },
  { C: Canais, enter: "slideU", cam: [[1.0, 0, 0], [1.06, 0, -30]], hits: [33.05] },
  { C: Painel, enter: "zoomOut", cam: [[1.12, 150, 30], [1.0, 0, 0]] },
  { C: FollowUp, enter: "slideL", cam: [[1.07, 50, 0], [1.0, -30, 10]], hits: [40.52] },
  { C: Lembretes, enter: "wipe", cam: [[0.98, -70, 20], [1.1, 50, -20]], hits: [44.26, 45.56] },
  { C: Indicadores, enter: "slideU", cam: [[1.08, 60, -20], [1.0, -20, 0]], hits: [47.62] },
  { C: JaRecebe, enter: "circle", cam: [[1.0, 0, 0], [1.08, -30, -10]], hits: [54.9] },
  { C: Fecho, enter: "slideL", cam: [[1.1, 0, 30], [1.0, 0, 0]], hits: [56.38] },
];
const SCENES: Sc[] = [
  ...OLD.slice(0, 11).map((s, i) => ({ ...s, a: T_OLD[i], b: T_OLD[i + 1] })),
  { C: TempoReal, enter: "zoom", cam: [[1.08, 80, 20], [1.0, -30, 0]], hits: [51.03, 53.72], a: TR0, b: 54.55, nova: true },
  ...OLD.slice(11).map((s, j) => ({ ...s, a: T_OLD[11 + j], b: T_OLD[12 + j] })),
];
// início de cada cena no tempo novo
const TN = SCENES.map((s) => (s.nova ? s.a : toNew(s.a)));

export const VetsSalesV2: React.FC = () => {
  const tn = useCurrentFrame() / VS_FPS;
  const open = interpolate(tn, [0, 0.55], [1.3, 1], { ...cl, easing: OUT });
  return (
    <AbsoluteFill style={{ background: PAPER }}>
      {SCENES.map(({ C, enter, cam, hits, a, b, nova }, i) => {
        const a2 = TN[i];
        const b2 = i + 1 < TN.length ? TN[i + 1] : VS2_DUR;
        if (tn < a2 - 0.3 || tn > b2 + 0.35) return null;
        const e = io(tn, a2 - 0.28, a2 + 0.22);
        let style: React.CSSProperties = {};
        if (enter !== "none" && e < 1) {
          if (enter === "zoom") style = { opacity: e, transform: `scale(${(1.25 - 0.25 * e).toFixed(4)})` };
          if (enter === "zoomOut") style = { opacity: e, transform: `scale(${(0.82 + 0.18 * e).toFixed(4)})` };
          if (enter === "slideL") style = { transform: `translateX(${((1 - e) * 1920).toFixed(1)}px)` };
          if (enter === "slideU") style = { transform: `translateY(${((1 - e) * 1080).toFixed(1)}px)` };
          if (enter === "wipe") style = { clipPath: `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0)` };
          if (enter === "circle") style = { clipPath: `circle(${(e * 1150).toFixed(0)}px at 960px 540px)` };
        }
        const next = SCENES[i + 1];
        const en = next ? io(tn, TN[i + 1] - 0.28, TN[i + 1] + 0.22) : 0;
        if (next && en > 0) {
          if (next.enter === "slideL") style = { ...style, transform: `translateX(${(-en * 640).toFixed(1)}px)` };
          if (next.enter === "slideU") style = { ...style, transform: `translateY(${(-en * 360).toFixed(1)}px)` };
          if (next.enter === "zoomOut") style = { ...style, transform: `scale(${(1 + en * 0.25).toFixed(4)})`, opacity: 1 - en };
        }
        const t = nova ? tn : toOld(tn);
        return (
          <AbsoluteFill key={i} style={{ ...style, background: PAPER, overflow: "hidden" }}>
            <AbsoluteFill style={i === 0 ? { transform: `scale(${open.toFixed(4)})` } : undefined}>
              <Cam t={t} a={a} b={b} from={cam[0]} to={cam[1]} hits={hits}><C t={t} /></Cam>
            </AbsoluteFill>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

